from pathlib import Path
import re,json
OUT=Path.cwd()/'outputs/audit-2026-10-09'
tables=[]
def t(name,domain,phase,change,purpose,fields,checks='',indexes='',mutable=True,resource_kind=None):
    cols=['id text PRIMARY KEY','created_at timestamptz NOT NULL DEFAULT now()']
    if mutable:cols+=['updated_at timestamptz NOT NULL DEFAULT now()','version integer NOT NULL DEFAULT 1 CHECK (version > 0)']
    if resource_kind:
        cols+= [f"resource_kind text NOT NULL DEFAULT '{resource_kind}' CHECK (resource_kind = '{resource_kind}')"]
        checks+=f';FOREIGN KEY (id, resource_kind) REFERENCES resource(id, kind)'
    cols += [x.strip() for x in fields.split(';') if x.strip()]
    tables.append(dict(name=name,domain=domain,phase=phase,change=change,purpose=purpose,columns=cols,constraints=[x.strip() for x in checks.split(';') if x.strip()],indexes=[x.strip() for x in indexes.split(';') if x.strip()]))

# 身份、权限、私密记录。全部名称为目标设计，不表示现库已迁移。
t('app_user','身份','R1','扩展User','游客之外的统一账号，注销保留匿名交易主体',"phone_cipher text;phone_hash text UNIQUE;username text UNIQUE;password_hash text;nickname text NOT NULL;avatar_asset_id text REFERENCES media_asset(id);status text NOT NULL DEFAULT 'ACTIVE';deleted_at timestamptz;last_seen_at timestamptz", "CHECK (status IN ('ACTIVE','FROZEN','DELETED'));CHECK ((status='DELETED')=(deleted_at IS NOT NULL))")
t('auth_identity','身份','R2','新增','微信/Apple身份绑定，手机号继续由app_user管理',"user_id text NOT NULL REFERENCES app_user(id);provider text NOT NULL;app_scope text NOT NULL;subject_hash text NOT NULL;union_subject_hash text;verified_at timestamptz NOT NULL",'UNIQUE(provider,app_scope,subject_hash)','(user_id,provider)')
t('auth_session','身份','R1','扩展AuthSession','APP/ADMIN短期access及可撤销refresh会话',"user_id text NOT NULL REFERENCES app_user(id);kind text NOT NULL;access_hash text NOT NULL UNIQUE;refresh_hash text NOT NULL UNIQUE;access_expires_at timestamptz NOT NULL;refresh_expires_at timestamptz NOT NULL;csrf_hash text;device_id text;revoked_at timestamptz", "CHECK(kind IN ('APP','ADMIN'));CHECK(refresh_expires_at>access_expires_at)",'(user_id,revoked_at)')
t('consumed_refresh','身份','R1','保留ConsumedRefresh','已消费刷新令牌，重放撤销原会话',"token_hash text NOT NULL UNIQUE;session_id text NOT NULL REFERENCES auth_session(id);expires_at timestamptz NOT NULL",indexes='(expires_at)',mutable=False)
t('otp_challenge','身份','R1','扩展OtpChallenge','短信挑战，不存明文验证码',"phone_hash text NOT NULL;purpose text NOT NULL;code_hash text NOT NULL;attempts integer NOT NULL DEFAULT 0;expires_at timestamptz NOT NULL;consumed_at timestamptz;provider_request_id text;delivery_state text NOT NULL",'CHECK(attempts BETWEEN 0 AND 5)','(phone_hash,purpose,created_at)',False)
t('rate_limit','身份','R1','保留RateLimit','基础数据库限流，必要时缓存加速',"limit_key text NOT NULL UNIQUE;count integer NOT NULL;expires_at timestamptz NOT NULL",'CHECK(count>=0)','(expires_at)')
t('access_role','身份','R1','替代roles枚举配置','角色与权限码，权限码目录由代码版本维护',"code text NOT NULL UNIQUE;name text NOT NULL;permission_codes text[] NOT NULL DEFAULT '{}';active boolean NOT NULL DEFAULT true")
t('user_role','身份','R1','新增','多角色授予；老师资源归属仍由teacher_staff/course_staff约束',"user_id text NOT NULL REFERENCES app_user(id);role_id text NOT NULL REFERENCES access_role(id);granted_by text NOT NULL REFERENCES app_user(id);reason text NOT NULL;revoked_at timestamptz",'','(user_id,role_id) WHERE revoked_at IS NULL UNIQUE')
t('tag','身份内容','R1','规范化tags','兴趣和资源标签字典',"code text NOT NULL UNIQUE;name text NOT NULL;parent_id text REFERENCES tag(id);active boolean NOT NULL DEFAULT true")
t('user_tag','身份内容','R1','替代User.tags','用户自主兴趣',"user_id text NOT NULL REFERENCES app_user(id);tag_id text NOT NULL REFERENCES tag(id)",'UNIQUE(user_id,tag_id)',mutable=False)
t('consent_record','身份','R1','新增','政策版本和非必要数据处理同意/撤回',"user_id text NOT NULL REFERENCES app_user(id);policy_code text NOT NULL;policy_version text NOT NULL;purpose text NOT NULL;accepted boolean NOT NULL;acted_at timestamptz NOT NULL;source text NOT NULL",indexes='(user_id,purpose,acted_at)',mutable=False)
t('media_asset','内容','R1','扩展MediaAsset','对象存储元数据、转码和审核；长期URL不出现在用户响应',"uploader_id text NOT NULL REFERENCES app_user(id);storage_key text NOT NULL UNIQUE;name text NOT NULL;mime text NOT NULL;bytes bigint NOT NULL;sha256 text NOT NULL;status text NOT NULL;visibility text NOT NULL;duration_seconds integer;provider_asset_id text;variants jsonb NOT NULL DEFAULT '{}';failure_code text",'CHECK(bytes>=0);CHECK(duration_seconds IS NULL OR duration_seconds>=0);CHECK(status IN (\'UPLOADING\',\'PROCESSING\',\'REVIEW\',\'READY\',\'REJECTED\',\'DELETED\'))','(uploader_id,created_at);(status,created_at)')
t('resource','内容','R1','新增统一资源注册','强FK的公共内容身份；此表是发布状态唯一权威',"kind text NOT NULL;title text NOT NULL;summary text NOT NULL DEFAULT '';cover_asset_id text REFERENCES media_asset(id);owner_id text REFERENCES app_user(id);publish_state text NOT NULL DEFAULT 'DRAFT';visibility text NOT NULL DEFAULT 'PUBLIC';membership_tier integer;category_code text NOT NULL;is_demo boolean NOT NULL DEFAULT false;featured_rank integer;published_at timestamptz", "UNIQUE(id,kind);CHECK(kind IN ('ARTICLE','TEACHER','COURSE','PRODUCT','EVENT','LIVE','THREAD'));CHECK(publish_state IN ('DRAFT','REVIEW','PUBLISHED','REJECTED','ARCHIVED'));CHECK(visibility IN ('PUBLIC','MEMBER','COURSE','PRIVATE'));CHECK(membership_tier IS NULL OR membership_tier BETWEEN 1 AND 3)",'(kind,publish_state,published_at,id);(kind,category_code,publish_state)')
t('resource_tag','内容','R1','新增','资源标签关系',"resource_id text NOT NULL REFERENCES resource(id);tag_id text NOT NULL REFERENCES tag(id)",'UNIQUE(resource_id,tag_id)',mutable=False)
t('source_evidence','内容治理','R1','新增','经典版本、译注版权、名师背景、文化溯源及资质证据',"kind text NOT NULL;title text NOT NULL;author text;edition text;source_url text;proof_asset_id text REFERENCES media_asset(id);rights_holder text;license_scope text;valid_from timestamptz;valid_until timestamptz;review_state text NOT NULL;reviewer_id text REFERENCES app_user(id);review_note text",'CHECK(valid_until IS NULL OR valid_from IS NULL OR valid_until>valid_from)')
t('resource_evidence','内容治理','R1','新增','资源与核验证据关联',"resource_id text NOT NULL REFERENCES resource(id);evidence_id text NOT NULL REFERENCES source_evidence(id);purpose text NOT NULL",'UNIQUE(resource_id,evidence_id,purpose)',mutable=False)
