t('trade_order','交易','R1','替代开发Order','订单商务状态与支付/退款分离；不同履约种类不混单',"order_no text NOT NULL UNIQUE;user_id text NOT NULL REFERENCES app_user(id);kind text NOT NULL;request_key text NOT NULL;request_hash text NOT NULL;state text NOT NULL DEFAULT 'PENDING';currency char(3) NOT NULL;minor_exponent integer NOT NULL DEFAULT 2;subtotal bigint NOT NULL;discount_total bigint NOT NULL DEFAULT 0;shipping_total bigint NOT NULL DEFAULT 0;payable_total bigint NOT NULL;paid_total bigint NOT NULL DEFAULT 0;refunded_total bigint NOT NULL DEFAULT 0;address_snapshot_cipher text;pricing_snapshot jsonb NOT NULL;quote_hash text NOT NULL;expires_at timestamptz NOT NULL;paid_at timestamptz;closed_at timestamptz;completed_at timestamptz;close_reason text", "UNIQUE(user_id,request_key);CHECK(state IN ('PENDING','PAID','FULFILLING','COMPLETED','CLOSED'));CHECK(subtotal>=0 AND discount_total>=0 AND shipping_total>=0 AND payable_total=subtotal-discount_total+shipping_total AND payable_total>=0);CHECK(paid_total>=0 AND refunded_total>=0 AND refunded_total<=paid_total)",'(user_id,created_at,id);(state,expires_at)')
